const DIAS_ORDEN = ['lunes','martes','miercoles','jueves','viernes','sabado','domingo'];
const ABREV_MAP = { lun:'lunes', mar:'martes', mie:'miercoles', jue:'jueves', vie:'viernes', sab:'sabado', dom:'domingo' };

function normalizar(str) {
  return (str || '').normalize('NFD').replace(/[̀-ͯ]/g, '').toLowerCase().trim();
}

function parseCSV(text) {
  const rows = [];
  let row = [], field = '', inQuotes = false;
  for (let i = 0; i < text.length; i++) {
    const c = text[i];
    if (inQuotes) {
      if (c === '"') { if (text[i+1] === '"') { field += '"'; i++; } else inQuotes = false; }
      else field += c;
    } else {
      if (c === '"') inQuotes = true;
      else if (c === ',') { row.push(field); field = ''; }
      else if (c === '\n') { row.push(field); rows.push(row); row = []; field = ''; }
      else if (c === '\r') { /* skip */ }
      else field += c;
    }
  }
  if (field.length || row.length) { row.push(field); rows.push(row); }
  return rows;
}

function normalizarHora(h) {
  if (h.includes(':')) { const [hh, mm] = h.split(':'); return hh.padStart(2,'0') + ':' + mm.padStart(2,'0'); }
  return h.padStart(2,'0') + ':00';
}

const DIA_RE = '(?:Lun|Mar|Mi[eé]|Jue|Vie|Sab|S[aá]b|Dom)';

function splitBloques(texto) {
  return texto.split(/,/).flatMap(part =>
    part.split(new RegExp('\\s+y\\s+(?=' + DIA_RE + '\\.?\\s)', 'i'))
  ).map(s => s.trim()).filter(Boolean);
}

function parseHorario(textoOriginal) {
  const texto = (textoOriginal || '').replace(/(\d{1,2})[.,](\d{2})(?!\d)/g, '$1:$2');
  const horarios = {};
  DIAS_ORDEN.forEach(d => horarios[d] = []);
  const segmentos = splitBloques(texto);
  for (const seg of segmentos) {
    const m = seg.match(/^(Lun|Mar|Mi[eé]|Jue|Vie|Sab|S[aá]b|Dom)\.?\s*(?:a\s+(Lun|Mar|Mi[eé]|Jue|Vie|Sab|S[aá]b|Dom)\.?)?\s+(.*)$/i);
    if (!m) continue;
    const diaInicioAbr = normalizar(m[1]).slice(0,3);
    const diaFinAbr = m[2] ? normalizar(m[2]).slice(0,3) : null;
    const resto = m[3];
    const diaInicio = ABREV_MAP[diaInicioAbr];
    const diaFin = diaFinAbr ? ABREV_MAP[diaFinAbr] : diaInicio;
    if (!diaInicio || !diaFin) continue;

    let diasSegmento;
    if (diaFinAbr && diaInicioAbr === diaFinAbr) {
      // "Lun a Lun" (mismo dia explicito al principio y al final) = todos los dias, no un solo dia
      diasSegmento = DIAS_ORDEN.slice();
    } else {
      const idxInicio = DIAS_ORDEN.indexOf(diaInicio);
      const idxFin = DIAS_ORDEN.indexOf(diaFin);
      diasSegmento = [];
      for (let i = idxInicio; i <= idxFin; i++) diasSegmento.push(DIAS_ORDEN[i]);
    }

    const franjasTexto = resto.split(/\s+y\s+/i);
    for (const franjaTexto of franjasTexto) {
      const fm = franjaTexto.match(/(\d{1,2}(?::\d{2})?)\s*a\s*(\d{1,2}(?::\d{2})?)\s*hs?/i);
      if (!fm) continue;
      const desde = normalizarHora(fm[1]);
      const hasta = normalizarHora(fm[2]);
      diasSegmento.forEach(d => horarios[d].push({ desde, hasta }));
    }
  }
  return horarios;
}

// Parsea una o mas franjas horarias SUELTAS, sin nombre de dia adelante
// (para el texto de una excepcion puntual por fecha, ej "9 a 13hs" o "9 a 13hs, 16 a 18hs").
function parseFranjasSueltas(textoOriginal) {
  const texto = (textoOriginal || '').replace(/(\d{1,2})[.,](\d{2})(?!\d)/g, '$1:$2');
  const partes = texto.split(/,|\s+y\s+/i).map(s => s.trim()).filter(Boolean);
  const franjas = [];
  for (const p of partes) {
    const fm = p.match(/(\d{1,2}(?::\d{2})?)\s*a\s*(\d{1,2}(?::\d{2})?)\s*hs?/i);
    if (fm) franjas.push({ desde: normalizarHora(fm[1]), hasta: normalizarHora(fm[2]) });
  }
  return franjas;
}

function enHorarioAhora(horarios, ahora) {
  const diaActual = DIAS_ORDEN[ahora.weekday - 1];
  const horaActual = ahora.toFormat('HH:mm');
  const franjasHoy = horarios[diaActual] || [];
  return franjasHoy.some(f => horaActual >= f.desde && horaActual < f.hasta);
}

function parseFechaSheet(str) {
  const m = (str || '').trim().match(/^(\d{1,2})\/(\d{1,2})\/(\d{2,4})$/);
  if (!m) return null;
  let [, d, mo, y] = m;
  y = y.length === 2 ? ('20' + y) : y;
  return { day: parseInt(d, 10), month: parseInt(mo, 10), year: parseInt(y, 10) };
}

const sucursalId = $('Preparar derivación').item.json.sucursal;
const csvRaw = $input.first().json.data;
if (!csvRaw) throw new Error('No llegó el CSV de la sheet — revisar Response Format del nodo Fetch horarios sheet');

const rows = parseCSV(csvRaw);
const headers = rows[0].map(h => normalizar(h));
const idxSucursal = headers.indexOf('sucursal');
const idxHorario = headers.indexOf('horario');

const fila = rows.slice(1).find(r => normalizar(r[idxSucursal]) === normalizar(sucursalId));
if (!fila) throw new Error('No se encontró la sucursal "' + sucursalId + '" en la sheet');

const horarioTexto = fila[idxHorario];
const horariosSucursal = parseHorario(horarioTexto);

const ahora = DateTime.now().setZone('America/Argentina/Tucuman');

// --- Excepciones puntuales por fecha ("dias de atencion particular") + horarios por vendedor:
// ambas tablas viven mas abajo en la misma sheet, comparten la misma fila de encabezados
// (columnas "Sucursal,Fecha,Horario" para excepciones, y "Horarios Vendedores,Email/Mail,
// Horario de Trabajo" para vendedores), y sus filas de datos estan intercaladas.
let vendedoresEnHorario = null;
const excepciones = [];
const idxHeaderVendedores = rows.findIndex(r => r.some(c => normalizar(c) === 'horarios vendedores'));
if (idxHeaderVendedores !== -1) {
  const headerFila = rows[idxHeaderVendedores].map(h => normalizar(h));
  const idxNombreVend = headerFila.indexOf('horarios vendedores');
  const idxEmailVend = headerFila.indexOf('email') !== -1 ? headerFila.indexOf('email') : headerFila.indexOf('mail');
  const idxHorarioVend = headerFila.indexOf('horario de trabajo');
  const idxSucursalExc = headerFila.indexOf('sucursal');
  const idxFechaExc = headerFila.indexOf('fecha');
  const idxHorarioExc = headerFila.indexOf('horario');

  if (idxEmailVend !== -1 && idxHorarioVend !== -1) vendedoresEnHorario = [];

  for (let i = idxHeaderVendedores + 1; i < rows.length; i++) {
    const r = rows[i];

    if (vendedoresEnHorario !== null) {
      const nombreVend = (r[idxNombreVend] || '').trim();
      const emailVend = (r[idxEmailVend] || '').trim();
      const horarioVendTexto = r[idxHorarioVend] || '';
      if (nombreVend && emailVend && horarioVendTexto) {
        const horariosVend = parseHorario(horarioVendTexto);
        if (enHorarioAhora(horariosVend, ahora)) vendedoresEnHorario.push(emailVend);
      }
    }

    if (idxFechaExc !== -1 && idxHorarioExc !== -1) {
      const fechaTexto = (r[idxFechaExc] || '').trim();
      const fecha = parseFechaSheet(fechaTexto);
      if (fecha) {
        excepciones.push({
          sucursal: idxSucursalExc !== -1 ? normalizar(r[idxSucursalExc]) : '',
          fecha,
          texto: (r[idxHorarioExc] || '').trim(),
        });
      }
    }
  }
}

function buscarExcepcion(fecha) {
  return excepciones.find(e =>
    (!e.sucursal || e.sucursal === normalizar(sucursalId)) &&
    e.fecha.day === fecha.day && e.fecha.month === fecha.month && e.fecha.year === fecha.year
  );
}

// Franjas horarias efectivas para una fecha puntual: respeta una excepcion cargada para
// ese dia ("Cerrado todo el dia", o un horario especial puntual); si no hay excepcion,
// usa el horario semanal normal de la sucursal.
function franjasParaFecha(fechaDT) {
  const exc = buscarExcepcion(fechaDT);
  if (exc) {
    if (normalizar(exc.texto).includes('cerrado')) return [];
    const franjasExc = parseFranjasSueltas(exc.texto);
    if (franjasExc.length > 0) return franjasExc;
    // Texto de excepcion no reconocido (ni "cerrado" ni un horario parseable):
    // mejor no romper el chequeo normal por un dato mal cargado en la sheet.
  }
  const diaSemana = DIAS_ORDEN[fechaDT.weekday - 1];
  return horariosSucursal[diaSemana] || [];
}

const horaActual = ahora.toFormat('HH:mm');
const franjasHoy = franjasParaFecha(ahora);
const enHorario = franjasHoy.some(f => horaActual >= f.desde && horaActual < f.hasta);

let proximoTexto = null;
if (!enHorario) {
  const franjaFutura = franjasHoy.find(f => f.desde > horaActual);
  if (franjaFutura) {
    proximoTexto = 'hoy a las ' + franjaFutura.desde + ' hs';
  } else {
    for (let i = 1; i <= 14; i++) {
      const fechaFutura = ahora.plus({ days: i });
      const franjas = franjasParaFecha(fechaFutura);
      if (franjas.length > 0) {
        const dia = DIAS_ORDEN[fechaFutura.weekday - 1];
        proximoTexto = (i === 1 ? 'mañana' : 'el ' + dia) + ' a las ' + franjas[0].desde + ' hs';
        break;
      }
    }
    if (!proximoTexto) proximoTexto = 'en el próximo horario de atención';
  }
}

return [{ json: { en_horario: enHorario, proximo_texto: proximoTexto, vendedores_en_horario: vendedoresEnHorario } }];

