const rows = $input.all().map(i => i.json);

// Para agregar una columna nueva, sumar una línea acá — nada más hay que tocar.
const COLUMNAS = [
  { header: 'Celular',  get: r => r.phone },
  { header: 'Nombre',   get: r => r.nombre_cliente || r.phone },
  { header: 'Empresa',  get: r => r.empresa || '' },
  { header: 'Asignado', get: r => r.etiqueta || '' },
  { header: 'Sucursal', get: r => r.sucursal || '' },
  { header: 'Estado',   get: r => r.esperando_respuesta ? 'esperando' : 'respondido' }
];

function escaparCSV(valor) {
  const texto = String(valor ?? '');
  if (texto.includes(',') || texto.includes('"') || texto.includes('\n')) {
    return '"' + texto.replace(/"/g, '""') + '"';
  }
  return texto;
}

const encabezado = COLUMNAS.map(c => escaparCSV(c.header)).join(',');
const filas = rows
  .filter(r => r.phone)
  .map(r => COLUMNAS.map(c => escaparCSV(c.get(r))).join(','));

const csv = [encabezado, ...filas].join('\n');

return [{ json: { csv } }];

