const ctx = $('Contexto usuario reasignar').item.json;
const rows = $input.all().map(i => i.json);
const actual = rows[0] || {};

if (ctx.rol === 'vendedor') {
  if (!actual.vendedor_id || actual.vendedor_id !== ctx.user_id) {
    throw new Error('FORBIDDEN: solo podés derivar tus propios clientes');
  }
}

const sucursales = ctx.sucursales || [];
if (!actual.sucursal || !sucursales.includes(actual.sucursal)) {
  throw new Error('FORBIDDEN: la conversación no pertenece a tu sucursal');
}

return [{ json: { phone: ctx.phone, vendedor_id: ctx.vendedor_id } }];

const original = $('Agrupar contactos').item.json.contactos;
const cache = $input.all().map(i => i.json);
const cacheByPhone = {};
cache.forEach(c => { if (c.phone) cacheByPhone[c.phone] = c; });

const CINCO_DIAS_MS = 5 * 24 * 60 * 60 * 1000;
const ahora = Date.now();

const necesitanRefresh = [];
const resultado = original.map(c => {
  const cached = cacheByPhone[c.phone];
  const foto_url = cached?.foto_url || null;
  const actualizada = cached?.foto_actualizada_at ? new Date(cached.foto_actualizada_at).getTime() : 0;
  const estaVieja = (ahora - actualizada) > CINCO_DIAS_MS;
  if (!foto_url || estaVieja) necesitanRefresh.push(c.phone);
  return { ...c, foto_url };
});

return [{ json: { resultado, necesitanRefresh } }];

const item = $input.first().json;
const phones = item.necesitanRefresh || [];
return phones.map(phone => ({ json: { phone } }));

