const body = input.body || {};
if (!token) throw new Error('UNAUTHORIZED');
if (!body.phone || !body.fileName || !body.fileBase64) throw new Error('MISSING_PARAMS');

const MAX_BASE64_CHARS = 15 * 1024 * 1024 * 1.4;
if (body.fileBase64.length > MAX_BASE64_CHARS) throw new Error('FILE_TOO_LARGE');

return [{ json: {
  token,
  phone: body.phone,
  fileName: body.fileName,
  mimeType: body.mimeType || 'application/octet-stream',
  fileBase64: body.fileBase64
} }];

const row = $input.first().json;
if (!row || !row.user_id) throw new Error('UNAUTHORIZED');
const user = row;
const { phone, fileName, mimeType, fileBase64 } = $('Extraer token archivo').item.json;
return [{ json: { phone, fileName, mimeType, fileBase64, nombre_vendedor: user.nombre, sucursales: user.sucursales || [] } }];

const rows = $json.resultado || [];
const contactos = rows
  .filter(r => r.phone)
  .map(r => ({
    phone:            r.phone,
    nombre_cliente:   r.nombre_cliente   || r.phone,
    empresa:          r.empresa          || null,
    etiqueta:         r.etiqueta         || null,
    sucursal:         r.sucursal         || null,
    vendedor_id:      r.vendedor_id      || null,
    vendedor_nombre:  r.vendedor_nombre  || null,
    bot_active:       r.bot_active !== undefined ? r.bot_active : true,
    pendiente_fuera_horario: r.pendiente_fuera_horario || false,
    updated_at:       r.updated_at       || null,
    estado:           r.esperando_respuesta ? 'esperando' : 'respondido',
    foto_url:         r.foto_url || null
  }));

contactos.sort((a, b) => {
  if (a.bot_active === b.bot_active) return 0;
  return a.bot_active ? 1 : -1;
});

return [{ json: { contactos } }];

const ctx = $('Contexto lista vendedores').item.json;
const sucursal = ctx.sucursal;
const selfId = ctx.user_id;
const todos = $input.all().map(i => i.json);
const vendedores = todos.filter(v =>
  v.rol === 'vendedor' &&
  v.id !== selfId &&
  Array.isArray(v.sucursales) && (!sucursal || v.sucursales.includes(sucursal))
);
return [{ json: { vendedores: vendedores.map(v => ({ id: v.id, nombre: v.nombre, email: v.email, rol: v.rol })) } }];

const body = $input.first().json.body || {};
const phone    = body.phone    || '';
const sucursal = body.sucursal || 'tucuman';

const CATEGORIAS_VALIDAS = ['minorista', 'mayorista_revendedor', 'proveedores'];
let categoria_destino = body.categoria_destino;
if (!CATEGORIAS_VALIDAS.includes(categoria_destino)) {
  categoria_destino = 'mayorista_revendedor';
}

if (!phone) throw new Error('MISSING_PHONE');

return [{ json: { phone, sucursal, categoria_destino } }];

const rpc = $('RPC derivar_inteligente').item.json;
return [{ json: {
  ok: true,
  derivar: true,
  fuera_horario: rpc.fuera_horario || false,
  vendedor_nombre: rpc.vendedor_nombre || 'un vendedor',
  proximo_texto: rpc.proximo_texto || null
} }];

const ctx = $('Verificar rol asignar').item.json;
const row = $input.first().json || {};
const sucursales = ctx.sucursales || [];
if (!row.sucursal || !sucursales.includes(row.sucursal)) {
  throw new Error('FORBIDDEN: la conversación no pertenece a tu sucursal');
}
return [{ json: { phone: ctx.phone, vendedor_id: ctx.vendedor_id } }];

const ctx = $('Contexto etiquetar').item.json;
const row = $input.first().json || {};
const sucursales = ctx.sucursales || [];
if (!row.sucursal || !sucursales.includes(row.sucursal)) {
  throw new Error('FORBIDDEN: la conversación no pertenece a tu sucursal');
}
return [{ json: { ok: true } }];

const ctx = $('Contexto usuario reactivar').item.json;
const row = $input.first().json || {};
const sucursales = ctx.sucursales || [];
if (!row.sucursal || !sucursales.includes(row.sucursal)) {
  throw new Error('FORBIDDEN: la conversación no pertenece a tu sucursal');
}
return [{ json: { ok: true } }];

const ctx = $('Contexto usuario enviar').item.json;
const row = $input.first().json || {};
const sucursales = ctx.sucursales || [];
if (!row.sucursal || !sucursales.includes(row.sucursal)) {
  throw new Error('FORBIDDEN: la conversación no pertenece a tu sucursal');
}
return [{ json: { phone: ctx.phone, mensaje: ctx.mensaje } }];

const ctx = $('Contexto usuario archivo').item.json;
const row = $input.first().json || {};
const sucursales = ctx.sucursales || [];
if (!row.sucursal || !sucursales.includes(row.sucursal)) {
  throw new Error('FORBIDDEN: la conversación no pertenece a tu sucursal');
}
return [{ json: { ok: true } }];

const items = $input.all();
let mensajes = [];
try {
  mensajes = items
    .map(i => i.json)
    .filter(r => r && r.message !== undefined && r.message !== null)
    .map(r => {
      const msg = typeof r.message === 'string' ? JSON.parse(r.message) : r.message;
      return { type: msg.type, content: msg.content || msg.data?.content || '', id: r.id };
    })
    .sort((a, b) => a.id - b.id);
} catch (e) {
  mensajes = [];
}
const transcript = mensajes
  .map(m => `${m.type === 'human' ? 'Cliente' : 'Bot/Vendedor'}: ${m.content}`)
  .join('\n');
return [{ json: { transcript: transcript || '(sin mensajes previos disponibles)' } }];

